import sys, json
for line in sys.stdin:
    line=line.rstrip('\n')
    if '|' not in line: continue
    i, mj = line.split('|',1)
    try: m=json.loads(mj)
    except Exception as e: print(i, 'bad json', e); continue
    def summ(d):
        keys=['mission_score','usable_fix_rate','false_fix_rate','abstain_rate','coverage','median_error_m','p10_error_m','p25_error_m','p75_error_m','model_bytes','latency_ms']
        return {k: d.get(k) for k in keys if k in d}
    print('EXP', i)
    print('  top:', {k:v for k,v in m.items() if not isinstance(v,(dict,list))})
    for k,v in m.items():
        if isinstance(v,dict):
            print('  ',k,':')
            for kk,vv in v.items():
                if isinstance(vv,dict): print('     ',kk, summ(vv) if summ(vv) else {a:b for a,b in vv.items() if not isinstance(b,(dict,list))})
                else: print('     ',kk, vv)
